CloudSignInOutcome CloudSignIn::failed(const std::string& code, const std::string& message, bool retryable)
{
    m_phase = CloudSignInPhase::Idle;
    m_token.clear();
    CloudSignInOutcome outcome;
    outcome.kind  = CloudSignInOutcome::Kind::Failed;
    outcome.error = AgentError{code, message, retryable};
    return outcome;
}

std::string CloudSignIn::link_url(const std::string& link) const
{
    // Obico's Terms and Privacy Policy until JusPrin's own are published.
    // JusPrin accounts are separate from Obico's.
    if (link == "terms")
        return "https://www.obico.io/terms.html";
    if (link == "privacy")
        return "https://www.obico.io/privacy.html";
    if (link == "reset_password")
        return m_server + "/accounts/password/reset/";
    return {};
}

std::optional<CloudAccountRecord> CloudSignIn::account() const
{
    if (!m_store.load)
        return std::nullopt;
    std::optional<CloudAccountRecord> record = m_store.load();
    if (!record || record->token.empty())
        return std::nullopt;
    return record;
}

